/* FC Barcelona DNA — blaugrana night navy, garnet and gold, més que un club */
.theme-barcelona-dna {
  --bg: oklch(0.213 0.072 278.4);
  --surface: oklch(0.255 0.084 276.8);
  --surface-2: oklch(0.301 0.103 276.8);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.725 0.055 280.2);
  --accent: oklch(0.462 0.185 8.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.814 0.166 89.2);
  --line: oklch(1 0 0 / 15%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.814 0.166 89.2);
  --danger: oklch(0.462 0.185 8.3);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Exo 2", sans-serif;
  --font-body: "Exo 2", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.08em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-barcelona-dna h1,
.theme-barcelona-dna h2,
.theme-barcelona-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-barcelona-dna { background-image: repeating-linear-gradient(90deg, oklch(0.35 0.14 15 / 12%) 0 80px, transparent 80px 160px); }
.theme-barcelona-dna h1 { text-transform: uppercase; }
.theme-barcelona-dna h1::after { content: ""; display: block; height: 3px; width: 5rem; margin-top: 0.6rem; background: var(--accent-2); }
.theme-barcelona-dna button { font-weight: 700; }

/* depth */
.theme-barcelona-dna thead th { background: var(--surface); color: var(--accent-2); text-transform: uppercase; letter-spacing: 0.08em; font-size: 0.78em; border-bottom: 2px solid var(--accent); }
.theme-barcelona-dna td { border-bottom: 1px solid var(--line); }
.theme-barcelona-dna tbody tr:hover { background: oklch(0.35 0.14 15 / 18%); }
.theme-barcelona-dna a { color: var(--accent-2); text-underline-offset: 3px; text-decoration-color: oklch(0.55 0.18 10 / 70%); }
.theme-barcelona-dna a:hover { text-decoration-color: var(--accent-2); text-decoration-thickness: 2px; }
.theme-barcelona-dna ::selection { background: oklch(0.462 0.185 8.3); color: oklch(1 0 0); }
.theme-barcelona-dna input:focus-visible, .theme-barcelona-dna select:focus-visible, .theme-barcelona-dna textarea:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 1px; }
.theme-barcelona-dna kbd { background: oklch(0.30 0.10 277); border: 1px solid var(--line); border-bottom-width: 3px; border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); }
.theme-barcelona-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-barcelona-dna ::-webkit-scrollbar-track { background: oklch(0.18 0.06 278); }
.theme-barcelona-dna ::-webkit-scrollbar-thumb { background: oklch(0.42 0.15 10); border-radius: 5px; border: 2px solid oklch(0.18 0.06 278); }
.theme-barcelona-dna ::-webkit-scrollbar-thumb:hover { background: oklch(0.50 0.17 10); }
.theme-barcelona-dna .label-caps { color: var(--accent-2); }
/* senyera strip — the Catalan bars from the crest */
.theme-barcelona-dna .themed-border { border-image: repeating-linear-gradient(90deg, oklch(0.814 0.166 89.2) 0 10px, oklch(0.55 0.21 25) 10px 20px) 1; }
.theme-barcelona-dna button:active { transform: translateY(1px); }

/* alt mode: auto-derived light variant */
.theme-barcelona-dna.alt-mode {
  --bg: oklch(0.98 0.012 278.4);
  --surface: oklch(0.955 0.015 278.4);
  --surface-2: oklch(0.92 0.020 278.4);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  /* daylight kit: faint blaugrana stripes survive the flip */
  background-image: repeating-linear-gradient(90deg, oklch(0.50 0.16 275 / 6%) 0 80px, oklch(0.50 0.19 15 / 6%) 80px 160px);
}
.theme-barcelona-dna.alt-mode tbody tr:hover { background: oklch(0.50 0.19 15 / 8%); }
.theme-barcelona-dna.alt-mode kbd { background: oklch(0.94 0.015 278); color: var(--fg); }
.theme-barcelona-dna.alt-mode ::-webkit-scrollbar-track { background: oklch(0.94 0.012 278); }
.theme-barcelona-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.55 0.16 275); border-color: oklch(0.94 0.012 278); }
.theme-barcelona-dna.alt-mode .label-caps { color: oklch(0.55 0.13 85); }
.theme-barcelona-dna.alt-mode a { color: oklch(0.462 0.185 8.3); text-decoration-color: oklch(0.65 0.13 85); }
.theme-barcelona-dna.alt-mode thead th { color: oklch(0.55 0.13 85); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
